"use client";
import Link from 'next/link';
import { useRouter } from 'next/navigation';
import { useState,type FormEvent } from 'react';
import { api,type Details } from '../lib/api';
import { useResource } from '../lib/use-resource';
import { saveToken } from '../login/auth_service';
import { Brand } from './Header';
export default function AuthForm({register=false}:{register?:boolean}){const router=useRouter();const {data:illustration}=useResource<Details>(`/pokemon/${register?133:25}`);const[error,setError]=useState(''),[busy,setBusy]=useState(false),[visible,setVisible]=useState(false);async function submit(e:FormEvent<HTMLFormElement>){e.preventDefault();const form=new FormData(e.currentTarget);setError('');if(register&&form.get('password')!==form.get('confirm')){setError('As senhas devem ser iguais.');return;}setBusy(true);try{const response=await api<{access_token:string}>(register?'/auth/register':'/auth/login',{method:'POST',body:JSON.stringify({email:form.get('email'),password:form.get('password'),...(register?{name:form.get('name')}:{rememberMe:form.get('remember')==='on'})})});saveToken(response.access_token,form.get('remember')==='on');const next=new URLSearchParams(window.location.search).get('next');router.replace(next?.startsWith('/')&&!next.startsWith('//')?next:'/dashboard');}catch(e){setError(e instanceof Error?e.message:'Não foi possível entrar.');}finally{setBusy(false);}}return <main className="pk-auth-page"><aside><Brand/><div className="pk-auth-illustration">{illustration?.spriteUrl?<img src={illustration.spriteUrl} alt={register?"Eevee":"Pikachu"}/>:<span className="pk-auth-symbol" aria-hidden>◒</span>}</div><blockquote>“A jornada de mil batalhas começa com uma única Pokébola.”<small>— Professor Carvalho</small></blockquote></aside><section><Link className="pk-back" href="/">← Voltar para o início</Link><form onSubmit={submit} className="pk-auth-form"><p className="pk-eyebrow">{register?'COMECE SUA JORNADA':'BEM-VINDO DE VOLTA'}</p><h1>{register?'Crie sua conta':'Entre na sua conta'}</h1><p>{register?'Cadastre-se gratuitamente e torne-se um treinador.':'Continue de onde parou em sua jornada Pokémon.'}</p>{error&&<div className="pk-notice" role="alert">{error}</div>}{register&&<label>Nome do treinador<input name="name" required minLength={3} maxLength={100} autoComplete="name" placeholder="Como devemos chamar você?"/></label>}<label>E-mail<input name="email" type="email" required autoComplete="email" placeholder="treinador@exemplo.com"/></label><label>Senha<div className="pk-password"><input aria-label="Senha" name="password" type={visible?'text':'password'} required minLength={6} autoComplete={register?'new-password':'current-password'} placeholder="Sua senha"/><button type="button" aria-label={visible?'Ocultar senha':'Mostrar senha'} onClick={()=>setVisible(v=>!v)}>{visible?'Ocultar':'Mostrar'}</button></div></label>{register?<label>Confirmar senha<input name="confirm" type={visible?'text':'password'} required minLength={6} autoComplete="new-password"/></label>:<label className="pk-checkbox"><input type="checkbox" name="remember"/> Lembrar de mim neste dispositivo</label>}<button className="pk-button" disabled={busy}>{busy?'Aguarde…':register?'Criar minha conta →':'Entrar na jornada →'}</button>{!register&&<Link href="/recuperar-senha">Esqueci minha senha</Link>}<p className="pk-auth-switch">{register?'Já possui uma conta?':'Ainda não tem uma conta?'} <Link href={register?'/login':'/cadastro'}>{register?'Entrar':'Criar conta'}</Link></p></form></section></main>;}

"use client";
import Link from 'next/link';
import {useState} from 'react';
import {api,type Capture} from '../lib/api';
import {useResource} from '../lib/use-resource';
import {Types,typeLabels} from './PokemonCard';
import CaptureModal from './CaptureModal';
import Modal from './Modal';
export default function Collection(){const{data,error,loading,reload}=useResource<Capture[]>('/captured-pokemon');const[viewing,setViewing]=useState<Capture|null>(null);const[search,setSearch]=useState(''),[type,setType]=useState(''),[sort,setSort]=useState('recent'),[editing,setEditing]=useState<Capture|null|undefined>(undefined),[deleting,setDeleting]=useState<Capture|null>(null),[busy,setBusy]=useState(false),[message,setMessage]=useState('');const filtered=(data??[]).filter(c=>(c.pokemon.name+' '+(c.nickname??'')+' '+c.pokemon.pokedexNumber).toLowerCase().includes(search.toLowerCase())&&(!type||[c.pokemon.type,c.pokemon.type2].includes(type))).sort((a,b)=>sort==='name'?a.pokemon.name.localeCompare(b.pokemon.name):sort==='level'?b.level-a.level:new Date(b.captureDate).getTime()-new Date(a.captureDate).getTime());async function remove(){if(!deleting)return;setBusy(true);try{await api(`/captured-pokemon/${deleting.id}`,{method:'DELETE'});setDeleting(null);setMessage('Captura excluída. As equipes e a progressão foram atualizadas.');reload();}catch(e){setMessage(e instanceof Error?e.message:'Falha ao excluir.');}finally{setBusy(false);}}
return <><p className="pk-eyebrow">MINHA COLEÇÃO</p><div className="pk-section-heading"><div><h1>Meus Pokémon</h1><p>{data?.length??0} Pokémon capturados em sua jornada.</p></div><button className="pk-button" onClick={()=>setEditing(null)}>＋ Capturar Pokémon</button></div>{message&&<p role="status" className="pk-notice">{message}</p>}<div className="pk-filter"><input aria-label="Pesquisar na coleção" value={search} onChange={e=>setSearch(e.target.value)} placeholder="Pesquisar na coleção…"/><select aria-label="Filtrar por tipo" value={type} onChange={e=>setType(e.target.value)}><option value="">Todos os tipos</option>{Object.entries(typeLabels).map(([v,l])=><option value={v} key={v}>{l}</option>)}</select><select aria-label="Ordenar capturas" value={sort} onChange={e=>setSort(e.target.value)}><option value="recent">Mais recentes</option><option value="name">Nome A–Z</option><option value="level">Maior nível</option></select></div>{loading?<p role="status">Carregando sua coleção…</p>:error?<p role="alert">{error} <button onClick={reload}>Tentar novamente</button></p>:<><div className="pk-collection-grid">{filtered.map(c=><article className="pk-capture pk-panel" key={c.id}><Link className={`pk-capture-art bg-${c.pokemon.type}`} href={`/pokedex/${c.pokemon.pokedexNumber}`}>{c.pokemon.spriteUrl&&<img src={c.pokemon.spriteUrl} alt={c.pokemon.name}/>}<small>Nv. {c.level}</small></Link><div><small>#{String(c.pokemon.pokedexNumber).padStart(3,'0')}</small><h2 className="capitalize">{c.nickname||c.pokemon.name}</h2><Types pokemon={c.pokemon}/><small>Capturado em {new Date(c.captureDate).toLocaleDateString('pt-BR')}</small><div className="pk-card-actions"><button aria-label={`Detalhes da captura de ${c.pokemon.name}`} onClick={()=>setViewing(c)}>◎</button><button aria-label={`Editar captura de ${c.pokemon.name}`} onClick={()=>setEditing(c)}>✎</button><button className="danger" aria-label={`Excluir captura de ${c.pokemon.name}`} onClick={()=>setDeleting(c)}>♜</button></div></div></article>)}</div>{filtered.length===0&&<p className="pk-notice">Nenhuma captura encontrada. Registre sua primeira descoberta ou ajuste os filtros.</p>}</>}{editing!==undefined&&<CaptureModal capture={editing??undefined} onClose={()=>setEditing(undefined)} onSaved={()=>{setMessage('Captura salva com sucesso.');reload();}}/>}{viewing&&<Modal title="Detalhes da captura" onClose={()=>setViewing(null)}><h3 className="capitalize">{viewing.nickname||viewing.pokemon.name}</h3><Types pokemon={viewing.pokemon}/><p>Nível {viewing.level} · Capturado em {new Date(viewing.captureDate).toLocaleDateString('pt-BR')}</p><p>{viewing.notes||'Sem observações.'}</p><Link className="pk-button secondary" href={`/pokedex/${viewing.pokemon.pokedexNumber}`}>Ver ficha da espécie</Link></Modal>}{deleting&&<Modal title="Excluir captura?" onClose={()=>{if(!busy)setDeleting(null);}}><p>Esta captura também será retirada das suas equipes. Deseja continuar?</p><div className="pk-modal-actions"><button className="pk-button secondary" disabled={busy} onClick={()=>setDeleting(null)}>Cancelar</button><button className="pk-button" disabled={busy} onClick={remove}>{busy?'Excluindo…':'Excluir captura'}</button></div></Modal>}</>;}

"use client";
import Link from 'next/link';
import {useResource} from '../lib/use-resource';
import type {Progress,Team,RankedTrainer} from '../lib/api';
import TrainerMetrics from './TrainerMetrics';
export default function Dashboard(){const progress=useResource<Progress>('/progression/me'),teams=useResource<Team[]>('/teams'),ranking=useResource<RankedTrainer[]>('/leaderboard'),badges=useResource<{id:number;obtainedAt:string;badge:{name:string}}[]>('/badges/trainer/me');const p=progress.data;const rank=ranking.data?.findIndex(t=>t.userId===p?.userId);const main=teams.data?.find(t=>t.isActive);if(progress.loading)return <p role="status">Carregando seu painel…</p>;if(progress.error||!p)return <p role="alert">{progress.error}<button onClick={progress.reload}>Tentar novamente</button></p>;return <><p className="pk-eyebrow">VISÃO GERAL</p><h1>Bem-vindo, Treinador!</h1><p>Mais uma etapa em sua jornada Pokémon.</p><section className="pk-callout pk-dashboard-banner"><div><span className="pk-main-tag">★ NÍVEL {p.level}</span><h2>Continue avançando, {p.trainerName}!</h2><p>Você está a apenas {p.experienceForNextLevel-p.experienceInCurrentLevel} XP de alcançar o próximo nível.</p><progress max={p.experienceForNextLevel} value={p.experienceInCurrentLevel}/><small>{p.experience.toLocaleString('pt-BR')} XP acumulados</small></div><span className="pk-banner-ball" aria-hidden>◒</span></section><TrainerMetrics progress={p} rank={rank!==undefined&&rank>=0?rank+1:undefined}/><div className="pk-details-bottom"><section className="pk-panel"><div className="pk-section-heading"><div><h2>Minha equipe principal</h2><p>{main?.name??'Monte sua formação favorita'}</p></div><Link href="/equipes">Gerenciar equipe →</Link></div>{teams.error?<p role="alert">{teams.error}</p>:teams.loading?<p role="status">Carregando equipe…</p>:main?<div className="pk-team-members">{main.teamPokemon.map(m=><Link key={m.capturedPokemonId} href={`/pokedex/${m.capturedPokemon.pokemon.pokedexNumber}`}>{m.capturedPokemon.pokemon.spriteUrl&&<img src={m.capturedPokemon.pokemon.spriteUrl} alt={m.capturedPokemon.pokemon.name}/>}<strong className="capitalize">{m.capturedPokemon.nickname||m.capturedPokemon.pokemon.name}</strong><small>Nv. {m.capturedPokemon.level}</small></Link>)}</div>:<p>Defina uma equipe principal em <Link href="/equipes">Minhas Equipes</Link>.</p>}</section><section className="pk-panel"><h2>Conquistas recentes</h2>{badges.error?<p role="alert">{badges.error}</p>:badges.data?.length?badges.data.slice(-4).reverse().map(b=><div className="pk-achievement" key={b.id}><span>♙</span><div><strong>{b.badge.name}</strong><small>{new Date(b.obtainedAt).toLocaleDateString('pt-BR')}</small></div></div>):<p>Suas insígnias aparecerão aqui conforme cumprir as metas.</p>}<Link href="/insignias">Ver todas as metas →</Link></section></div></>;}

"use client";
import Link from 'next/link';
import { useEffect,useState } from 'react';
import { api,type Details } from '../lib/api';
import PokemonCard from './PokemonCard';
export default function HomeContent(){const[pokemon,setPokemon]=useState<Details[]>([]),[error,setError]=useState('');useEffect(()=>{let active=true;Promise.all([25,4,1,7].map(id=>api<Details>(`/pokemon/${id}`))).then(value=>{if(active)setPokemon(value);}).catch(e=>{if(active)setError(e.message);});return()=>{active=false;};},[]);return <>
<section className="pk-hero"><div className="pk-container pk-hero-grid"><div><p className="pk-eyebrow">♫ UMA NOVA AVENTURA ESPERA POR VOCÊ</p><h1>Sua jornada<br/>Pokémon<br/><em>começa aqui!</em></h1><p>Explore o mundo Pokémon, capture seus favoritos, monte equipes incríveis e torne-se um verdadeiro Mestre Pokémon.</p><div className="pk-actions"><Link className="pk-button" href="/pokedex">⌕ Explorar Pokédex</Link><Link className="pk-button secondary" href="/cadastro">Começar jornada →</Link></div><small>Uma jornada de descobertas e conquistas.</small></div><div className="pk-hero-circle">{pokemon[0]?.spriteUrl&&<img src={pokemon[0].spriteUrl} alt="Pikachu"/>}<span className="pk-hero-tag">ELÉTRICO <strong>Pikachu</strong><small>#025</small></span></div></div></section>
<section className="pk-container pk-section"><p className="pk-eyebrow">CONHEÇA SEUS FAVORITOS</p><div className="pk-section-heading"><div><h2>Pokémon em destaque</h2><p>Comece explorando alguns dos Pokémon mais queridos pelos treinadores.</p></div><Link href="/pokedex">Ver Pokédex completa →</Link></div>{error?<p className="pk-notice" role="alert">{error} <Link href="/pokedex">Abrir catálogo</Link></p>:pokemon.length?<div className="pk-pokemon-grid">{pokemon.map(p=><PokemonCard key={p.pokedexNumber} pokemon={p}/>)}</div>:<p role="status">Carregando Pokémon da PokéAPI…</p>}</section>
<section className="pk-section pk-features"><div className="pk-container"><p className="pk-eyebrow">TUDO PARA SUA JORNADA</p><h2>Uma plataforma feita para treinadores</h2><p>Organize sua aventura e acompanhe cada evolução em um só lugar.</p><div className="pk-pokemon-grid">{[{title:'Pokédex completa',text:'Consulte informações detalhadas sobre as espécies de Kanto.',href:'/pokedex',icon:'▤'},{title:'Capture Pokémon',text:'Monte sua coleção e registre cada nova descoberta.',href:'/meus-pokemon',icon:'◒'},{title:'Monte suas equipes',text:'Crie equipes estratégicas com seus melhores Pokémon.',href:'/equipes',icon:'♧'},{title:'Suba no ranking',text:'Ganhe experiência e acompanhe sua classificação.',href:'/ranking',icon:'♜'}].map((f,i)=><Link className="pk-panel pk-feature" href={f.href} key={f.title}><span>{f.icon}</span><small>0{i+1}</small><h3>{f.title}</h3><p>{f.text}</p></Link>)}</div></div></section>
<section className="pk-container pk-section"><div className="pk-callout"><div><p className="pk-eyebrow">PRONTO PARA COMEÇAR?</p><h2>Torne-se um Mestre Pokémon</h2><p>Crie sua conta gratuita e dê o primeiro passo na sua jornada.</p></div><Link className="pk-button white" href="/cadastro">Criar minha conta →</Link></div></section>
</>;}

import Link from 'next/link';
import type { Pokemon } from '../lib/api';
export const typeLabels:Record<string,string>={normal:'Normal',fire:'Fogo',water:'Água',electric:'Elétrico',grass:'Planta',ice:'Gelo',fighting:'Lutador',poison:'Veneno',ground:'Terra',flying:'Voador',psychic:'Psíquico',bug:'Inseto',rock:'Pedra',ghost:'Fantasma',dragon:'Dragão',dark:'Sombrio',steel:'Aço',fairy:'Fada'};
export function Types({pokemon}:{pokemon:Pokemon}) { return <div className="pk-types">{[pokemon.type,pokemon.type2].filter(Boolean).map(type=><span className={`pk-type type-${type}`} key={type}>{typeLabels[type!]??type}</span>)}</div>; }
export default function PokemonCard({pokemon}:{pokemon:Pokemon}) {return <article className="pk-card"><Link href={`/pokedex/${pokemon.pokedexNumber}`} className={`pk-art bg-${pokemon.type}`}><span>#{String(pokemon.pokedexNumber).padStart(3,'0')}</span>{pokemon.spriteUrl ? <img src={pokemon.spriteUrl} alt={pokemon.name} loading="lazy"/> : <p>Imagem indisponível</p>}</Link><div className="pk-card-body"><h3 className="capitalize">{pokemon.name}</h3><Types pokemon={pokemon}/><Link className="pk-detail-link" href={`/pokedex/${pokemon.pokedexNumber}`}>Ver detalhes <span aria-hidden>→</span></Link></div></article>}

"use client";
import Link from 'next/link';
import {useState} from 'react';
import {useRouter} from 'next/navigation';
import {useResource} from '../lib/use-resource';
import type {Details} from '../lib/api';
import {isAuthenticated} from '../login/auth_service';
import {Types} from './PokemonCard';
import CaptureModal from './CaptureModal';
const labels:Record<string,string>={hp:'HP',attack:'Ataque',defense:'Defesa','special-attack':'Ataque especial','special-defense':'Defesa especial',speed:'Velocidade'};
export default function PokemonDetails({id}:{id:string}){const{data,error,loading,reload}=useResource<Details>(`/pokemon/${encodeURIComponent(id)}`);const[capture,setCapture]=useState(false),[saved,setSaved]=useState(false);const router=useRouter();if(loading)return <p className="pk-notice" role="status">Consultando os dados da espécie…</p>;if(error||!data)return <div className="pk-notice" role="alert">{error}<button onClick={reload} className="pk-button secondary">Tentar novamente</button></div>;return <><p className="pk-breadcrumb"><Link href="/">Início</Link> › <Link href="/pokedex">Pokédex</Link> › <span className="capitalize">{data.name}</span></p><article className="pk-species pk-panel"><div className={`pk-species-art bg-${data.type}`}><span>#{String(data.pokedexNumber).padStart(3,'0')}</span>{data.spriteUrl&&<img src={data.spriteUrl} alt={data.name}/>}</div><div className="pk-species-info"><p className="pk-eyebrow">CONHEÇA A ESPÉCIE</p><h1 className="capitalize">{data.name}</h1><Types pokemon={data}/><p>{data.description??'Descrição indisponível na PokéAPI.'}</p><div className="pk-species-facts"><div><small>ALTURA</small><strong>{data.height/10} m</strong></div><div><small>PESO</small><strong>{data.weight/10} kg</strong></div><div><small>HABILIDADES</small><strong className="capitalize">{data.ability}</strong></div></div><button className="pk-button" onClick={()=>{if(!isAuthenticated()){router.push(`/login?next=/pokedex/${id}`);return;}setCapture(true);}}>◒ Capturar Pokémon</button><small>Entre na sua conta para registrar uma captura.</small>{saved&&<p role="status">Captura registrada! <Link href="/meus-pokemon">Ver minha coleção</Link></p>}</div></article><div className="pk-details-bottom"><section className="pk-panel"><h2>Estatísticas base</h2>{data.stats.map(stat=><div className="pk-stat" key={stat.name}><span>{labels[stat.name]??stat.name}</span><strong>{stat.value}</strong><meter min={0} max={255} value={stat.value}>{stat.value}</meter></div>)}</section><section className="pk-panel"><h2>Linha evolutiva</h2><div className="pk-evolutions">{data.evolutions.map(p=><Link href={`/pokedex/${p.pokedexNumber}`} key={p.pokedexNumber}>{p.spriteUrl&&<img src={p.spriteUrl} alt={p.name}/>}<strong className="capitalize">{p.name}</strong><small>#{String(p.pokedexNumber).padStart(3,'0')}</small></Link>)}</div></section></div>{capture&&<CaptureModal pokemon={data} onClose={()=>setCapture(false)} onSaved={()=>setSaved(true)}/>}</>;}

"use client";
import {useState,type FormEvent} from 'react';
import {api,type UserProfile,type Progress} from '../lib/api';
import {useResource} from '../lib/use-resource';
export default function Profile(){const{data,error,loading,reload}=useResource<UserProfile>('/profiles/me');const progress=useResource<Progress>('/progression/me');const[message,setMessage]=useState(''),[busy,setBusy]=useState(false);async function save(e:FormEvent<HTMLFormElement>){e.preventDefault();const form=new FormData(e.currentTarget);setBusy(true);setMessage('');try{await api('/profiles/me',{method:'PUT',body:JSON.stringify({trainerName:form.get('trainerName'),email:form.get('email'),username:form.get('username')||undefined,bio:form.get('bio'),avatarUrl:form.get('avatarUrl')||undefined})});setMessage('Perfil atualizado com sucesso.');reload();window.dispatchEvent(new Event('profile-change'));}catch(e){setMessage(e instanceof Error?e.message:'Não foi possível salvar.');}finally{setBusy(false);}}if(loading&&!data)return <p role="status">Carregando perfil…</p>;if(error||!data)return <p role="alert">{error}<button onClick={reload}>Tentar novamente</button></p>;return <><p className="pk-eyebrow">CONTA</p><h1>Meu Perfil</h1><p>Gerencie seus dados e veja seu histórico como treinador.</p>{message&&<p role="status" className="pk-notice">{message}</p>}<div className="pk-profile-grid"><aside className="pk-panel pk-profile-card"><div className="pk-profile-cover"/>{data.profile?.avatarUrl?<img src={data.profile.avatarUrl} alt={`Avatar de ${data.name}`}/>:<div className="pk-avatar">{data.name.slice(0,1)}</div>}<h2>{data.name}</h2><p>@{data.profile?.username??'treinador'}</p><span className="pk-main-tag">★ TREINADOR NÍVEL {progress.data?.level??1}</span><hr/><p>Membro desde {new Date(data.createdAt).toLocaleDateString('pt-BR')}</p></aside><form className="pk-panel pk-form" onSubmit={save}><h2>Informações pessoais</h2><p>Seus dados de identificação</p><div className="pk-form-columns"><label>Nome do treinador<input name="trainerName" required minLength={3} maxLength={100} defaultValue={data.name}/></label><label>Nome de usuário<input name="username" minLength={3} maxLength={30} pattern="[a-zA-Z0-9_]+" defaultValue={data.profile?.username??''}/></label></div><label>E-mail<input name="email" type="email" required defaultValue={data.email}/></label><label>Biografia<textarea aria-label="Biografia" name="bio" maxLength={1000} defaultValue={data.profile?.bio??''}/></label><label>Imagem do perfil (URL)<input name="avatarUrl" type="url" placeholder="https://…" defaultValue={data.profile?.avatarUrl??''}/></label><div className="pk-modal-actions"><button className="pk-button" disabled={busy}>{busy?'Salvando…':'Salvar alterações'}</button></div></form></div><div className="pk-metrics"><div className="pk-panel"><div><small>Pokémon capturados</small><strong>{progress.data?.pokemonCaptured??'—'}</strong></div></div><div className="pk-panel"><div><small>Insígnias conquistadas</small><strong>{progress.data?.badges??'—'} / 8</strong></div></div><div className="pk-panel"><div><small>Experiência</small><strong>{progress.data?.experience??'—'} XP</strong></div></div></div></>;}

"use client";
import {useState,type FormEvent} from 'react';
import {api,type Team,type Capture} from '../lib/api';
import {useResource} from '../lib/use-resource';
import Modal from './Modal';
import {Types} from './PokemonCard';
function TeamForm({team,captures,onClose,onSaved}:{team:Team|null;captures:Capture[];onClose:()=>void;onSaved:()=>void}){const[selected,setSelected]=useState<number[]>(team?.teamPokemon.map(p=>p.capturedPokemonId)??[]),[busy,setBusy]=useState(false),[error,setError]=useState('');async function submit(e:FormEvent<HTMLFormElement>){e.preventDefault();setBusy(true);setError('');const form=new FormData(e.currentTarget);try{await api(team?`/teams/${team.id}`:'/teams',{method:team?'PATCH':'POST',body:JSON.stringify({name:form.get('name'),description:form.get('description'),isActive:form.get('isActive')==='on',capturedPokemonIds:selected})});onSaved();onClose();}catch(e){setError(e instanceof Error?e.message:'Falha ao salvar.');}finally{setBusy(false);}}return <Modal title={team?'Editar equipe':'Criar equipe'} onClose={onClose}><form className="pk-form" onSubmit={submit}>{error&&<p className="pk-notice" role="alert">{error}</p>}<label>Nome da equipe<input name="name" required maxLength={80} defaultValue={team?.name??''}/></label><label>Descrição<textarea aria-label="Descrição" name="description" maxLength={500} defaultValue={team?.description??''}/></label><label className="pk-checkbox"><input type="checkbox" name="isActive" defaultChecked={team?.isActive}/> Definir como equipe principal</label><p>Pokémon da equipe · {selected.length}/6</p><div className="pk-team-select">{captures.map(c=><label key={c.id} className={selected.includes(c.id)?'selected':''}><input type="checkbox" checked={selected.includes(c.id)} disabled={!selected.includes(c.id)&&selected.length>=6} onChange={e=>setSelected(ids=>e.target.checked?[...ids,c.id]:ids.filter(id=>id!==c.id))}/>{c.pokemon.spriteUrl&&<img src={c.pokemon.spriteUrl} alt=""/>}<strong className="capitalize">{c.nickname||c.pokemon.name}</strong><small>Nv. {c.level}</small></label>)}</div>{captures.length===0&&<p>Capture Pokémon antes de adicionar integrantes à equipe.</p>}<div className="pk-modal-actions"><button type="button" className="pk-button secondary" onClick={onClose} disabled={busy}>Cancelar</button><button className="pk-button" disabled={busy}>{busy?'Salvando…':'Salvar equipe'}</button></div></form></Modal>;}
export default function TeamBuilder(){const teams=useResource<Team[]>('/teams'),captures=useResource<Capture[]>('/captured-pokemon');const[editing,setEditing]=useState<Team|null|undefined>(undefined),[deleting,setDeleting]=useState<Team|null>(null),[message,setMessage]=useState(''),[busy,setBusy]=useState(false);async function remove(){if(!deleting)return;setBusy(true);try{await api(`/teams/${deleting.id}`,{method:'DELETE'});setDeleting(null);teams.reload();setMessage('Equipe excluída.');}catch(e){setMessage(e instanceof Error?e.message:'Falha ao excluir.');}finally{setBusy(false);}}return <><p className="pk-eyebrow">ESTRATÉGIA</p><div className="pk-section-heading"><div><h1>Minhas Equipes</h1><p>Crie formações equilibradas com seus Pokémon capturados.</p></div><button className="pk-button" onClick={()=>setEditing(null)}>＋ Criar equipe</button></div>{message&&<p role="status" className="pk-notice">{message}</p>}{teams.loading?<p role="status">Carregando equipes…</p>:teams.error?<p role="alert">{teams.error} <button onClick={teams.reload}>Tentar novamente</button></p>:<><p>{teams.data?.length??0} equipes · até seis Pokémon por formação</p>{teams.data?.map(team=>{const members=team.teamPokemon;const average=members.length?Math.round(members.reduce((sum,p)=>sum+p.capturedPokemon.level,0)/members.length):0;const types=new Set(members.flatMap(p=>[p.capturedPokemon.pokemon.type,p.capturedPokemon.pokemon.type2].filter(Boolean)));return <article className="pk-panel pk-team" key={team.id}><div className="pk-section-heading"><div>{team.isActive&&<span className="pk-main-tag">☆ EQUIPE PRINCIPAL</span>}<h2>{team.name}</h2><p>{team.description}</p></div><div className="pk-actions"><button className="pk-button secondary" onClick={()=>setEditing(team)}>✎ Editar equipe</button><button className="pk-icon-button danger" aria-label={`Excluir ${team.name}`} onClick={()=>setDeleting(team)}>×</button></div></div><div className="pk-team-members">{members.map(member=><div key={member.capturedPokemonId} className={`bg-${member.capturedPokemon.pokemon.type}`}>{member.capturedPokemon.pokemon.spriteUrl&&<img src={member.capturedPokemon.pokemon.spriteUrl} alt={member.capturedPokemon.pokemon.name}/>}<strong className="capitalize">{member.capturedPokemon.nickname||member.capturedPokemon.pokemon.name}</strong><small>Nv. {member.capturedPokemon.level}</small><Types pokemon={member.capturedPokemon.pokemon}/></div>)}</div>{members.length===0&&<p>Equipe sem integrantes. Edite para escolher suas capturas.</p>}<div className="pk-team-summary"><span>Nível médio <strong>{average}</strong>/100</span><meter min={0} max={100} value={average}/><span><strong>{types.size}</strong> tipos na equipe</span></div></article>;})}{teams.data?.length===0&&<p className="pk-notice">Você ainda não criou uma equipe.</p>}</>}{editing!==undefined&&(captures.loading?<p role="status">Carregando capturas…</p>:captures.error?<p role="alert">{captures.error}<button onClick={captures.reload}>Tentar novamente</button></p>:<TeamForm team={editing} captures={captures.data??[]} onClose={()=>setEditing(undefined)} onSaved={()=>{teams.reload();setMessage('Equipe salva com sucesso.');}}/>)}{deleting&&<Modal title="Excluir equipe?" onClose={()=>{if(!busy)setDeleting(null);}}><p>Os Pokémon continuarão na sua coleção.</p><div className="pk-modal-actions"><button className="pk-button secondary" disabled={busy} onClick={()=>setDeleting(null)}>Cancelar</button><button className="pk-button" disabled={busy} onClick={remove}>{busy?'Excluindo…':'Excluir equipe'}</button></div></Modal>}</>;}

