import { clearToken, getToken } from '../login/auth_service';
export const API = process.env.NEXT_PUBLIC_API_URL ?? 'http://localhost:3000/api';
export async function api<T>(path: string, options: RequestInit = {}): Promise<T> {
 const token = getToken();
 let response: Response;
 try { response = await fetch(`${API}${path}`, { ...options, credentials: 'include', headers: { 'Content-Type':'application/json', ...(token ? {Authorization:`Bearer ${token}`} : {}), ...options.headers } }); }
 catch { throw new Error('Não foi possível conectar ao servidor. Tente novamente.'); }
 if(response.status===401) { clearToken(); if(typeof window!=='undefined' && !path.startsWith('/auth/')) window.location.assign('/login'); }
 const body = await response.text();
 let data; try { data=body ? JSON.parse(body) : null; } catch { throw new Error('Resposta inválida do servidor.'); }
 if(!response.ok) throw new Error(Array.isArray(data?.message) ? data.message.join(' ') : data?.message ?? 'Não foi possível concluir a operação.');
 return data as T;
}
